<?php	include("../config.inc.php");	$Key = "IDCategoriaDocBV";	$Table = "CategoriaDocBV";			$id_div			= $_GET["id_div"];	$id_campo_code 	= $_GET["id_campo_code"];	$id_campo_name	= $_GET["id_campo_name"];	class Arbol {			function Arbol() {		}				/*Funciones para restricciones de permisos*/		function asginar_categorias(&$carpetas,$idCategoria){			if(!in_array ($idCategoria, $carpetas))			{				$carpetas[]=$idCategoria;			}			$sql = "SELECT IDCategoriaDocBV FROM CategoriaDocBV WHERE IDPadre='$idCategoria'";			$res_hijos=db_query($sql);			if($idCategoria!=""){				while($datos = db_fetch_object($res_hijos)){					$this->asginar_categorias($carpetas,$datos->IDCategoriaDocBV);				}			}		}		function carpetasRestringidas(&$carpetas,$cedula){			//este get_field solo aplica para listar por usuario sin el lista por modulo			//$cedula = get_field("RestriccionXUsuario","IDGrupoUsuarios","IDEmpleado",$cedula);						$sql1 = "SELECT IDSeccionSite FROM Permisos WHERE IDGrupoUsuarios='$cedula' AND IDModuloSite = 3 AND Permiso = 1";			$qry = db_query($sql1);						while($row = db_fetch_object($qry)){				$sql = "SELECT IDCategoriaDocBV FROM CategoriaDocBV WHERE IDCategoriaDocBV='$row->IDSeccionSite'";				$Recordset = db_query($sql);				while($datos = db_fetch_object($Recordset)){					$this->asginar_categorias($carpetas,$datos->IDCategoriaDocBV);				}			}		}		function lista($cedula){			$carpetas=array();			$this->carpetasRestringidas($carpetas,$cedula);			return $this->listaCategorias(0,$carpetas);		}				function listaCategorias($idPadre,$carpetas) {			global $Key, $Table;			$strCat = "";					if(count($carpetas)>0){				$idcarpetas=join($carpetas,",");				$condicion=" AND $Key NOT IN (".$idcarpetas.")";			}			$consulta = db_query("SELECT $Key, NombreItem FROM $Table WHERE IDPadre = ".$idPadre." $condicion");			while($rowsCat=db_fetch_object($consulta)){				$strCat.= "['".$rowsCat->$Key." $ ".$rowsCat->NombreItem."', null, ";				$strCat.= $this->listaCategorias($rowsCat->$Key,$carpetas);				$strCat.= "],";			}			return $strCat;		}		}	$cat = new Arbol();			?><html><head><title>Estructura de Categor&iacute;as Biblioteca Virtual</title><meta http-equiv="Content-Type" content="text/html; charset=iso-8859-1"><script language="JavaScript" src="../jscripts/tree.js?sp"></script><script language="JavaScript" src="../jscripts/tree_tpl.php?aO"></script><link rel="stylesheet" href="../styles.css" type="text/css"><script language="javascript">		function onDblClickCategoria(code,name){		self.opener.document.getElementById('<?php echo $id_campo_name ?>').value = name;		self.opener.document.getElementById('<?php echo $id_div ?>').value = code;		self.close();	}		var TREE_ITEMS = [ <?php echo $cat->lista($id); ?> ];	</script></head><body>    <table width=480 height=380 border=0 class=bordertable>     <tr class=maintitle>     <td>Seleccione la Categoria deseada</td>     </tr>     <tr class=row1>     <td valign=top>      <script language="JavaScript">	<!--//	new tree (TREE_ITEMS, TREE_TPL);	//-->	</script>	</td></tr>	</table></body></html><??>